type Query {
    show(id: ID!): Show
}

type Show {
    id: ID!
    title: String!
    reviews: [Review!]!
}

input ReviewInput {
    starRating: Int!
}

@DgsComponent
public class ShowDataFetcher {
    @DgsQuery
    public Show show(@InputArgument String id) {
        return service.findById(id);
    }
    @DgsSubscription
    public Publisher<Review> reviewAdded(...) {
        return sink.asFlux();
    }
}

@DgsDataLoader(name = "reviews")
public class ReviewsDataLoader 
    implements MappedBatchLoader<String, List<Review>> {

    public CompletionStage<Map<String, List<Review>>> load(Set<String> keys) {
        return CompletableFuture.supplyAsync(() -> 
            repo.findReviewsGroupedBy(keys));
    }
}

@PreAuthorize("hasRole('FINANCE_ADMIN')")
@DgsData(parentType = "Show", field = "cost")
public Double licensingCost(...) {
    return service.getCost();
}
